<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mpackingcode extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY . "mpackingcodemodel");        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $this->companyid = $ArrUserLoggedInfo['companyid'];        $this->userid = $ArrUserLoggedInfo['id'];        $this->limit = LIMITPERPAGE;    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $ArrData['Edit'] = $this->uri->segment(5);        $VarId = base64_decode(urldecode($this->uri->segment(4)));        if (is_numeric($VarId)) {            $ArrResults = $this->mpackingcodemodel->fnGetPackingCodeInfo('', '', $VarId, $this->companyid);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditpackingcode', $ArrData);    }    public function updatePackingCodeInfo() {        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $ArrResult = array();        $VarPackingName = xssclean($this->input->post('pn'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarPackingName <> '') {            $ArrUpdateData = array('id' => $VarId, 'packingname' => $VarPackingName, 'status' => $VarStatus,                'updatedby' => $this->userid, 'companyid' => $this->companyid, 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mpackingcodemodel->savePackingCodeInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function managepackingcode() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarPackingName = trim(xssclean($this->input->post('pn')));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $ArrDbCols = array('pn.packingname', 'pn.status', 'u.contactname', 'pn.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mpackingcode/managepackingcode/';            $config['total_rows'] = $this->mpackingcodemodel->fnCountPackingCode($VarPackingName, $VarStatus);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "pc.dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrPackingCodeList = $this->mpackingcodemodel->fnListPackingCode($VarPackingName, $VarStatus, $this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('PackingCode');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrPackingCodeList as $ObjUnit) {                $ArrFnlList[$i]['id'] = $ObjUnit->id;                $ArrFnlList[$i]['n'] = $ObjUnit->packingname;                $ArrFnlList[$i]['ub'] = $ObjUnit->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjUnit->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i A', strtotime($ObjUnit->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managepackingcode');        }    }    function changemStatus() {        $VarActDeactOption = xssclean($this->input->post('actdeactFabType'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->mpackingcodemodel->fnChangeComStat($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));        die;    }}